{
  "name": "ralph-loop",
  "version": "0.1.0",
  "description": "Minimal AI coding agent loop — no Docker needed",
  "type": "module",
  "exports": {
    ".": {
      "import": "./src/core/ralph-loop.ts",
      "types": "./src/core/ralph-loop.ts"
    },
    "./sources": {
      "import": "./src/core/sources.ts",
      "types": "./src/core/sources.ts"
    }
  },
  "scripts": {
    "dev": "npx tsx run/issues.ts",
    "dev:ui": "npx tsx run/dev-ui.ts",
    "dev:ui:wizard": "npx tsx run/dev-ui.ts --mode wizard",
    "ai:learn": "npx tsx run/learn.ts",
    "test": "vitest run --testTimeout=30000",
    "check": "tsc --noEmit",
    "clean-snapshots": "npx tsx run/clean-snapshots.ts"
  },
  "devDependencies": {
    "@types/node": "^25.9.1",
    "@types/react": "^19.2.17",
    "ink-testing-library": "^4.0.0",
    "tsx": "^4.0.0",
    "typescript": "^5.4.0",
    "vitest": "^4.1.7"
  },
  "dependencies": {
    "@inkjs/ui": "^2.0.0",
    "ink": "^7.1.0",
    "react": "^19.2.7"
  }
}
